-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"78296f45-5fb8-4b20-b6c2-257a0acb215f","n":1,"title":"الحروف التي تنطق ولا تكتب","passage":"تحتوي الكتابة العربية في كلمات محددة على حروف ينطق بها اللسان ولا تظهر في الرسم القياسي، كما في الألف الملفوظة بعد الهاء في «هذا». لا يجوز حذف حروف الكلمات الأخرى بالقياس دون قاعدة. نقرأ الكلمة بضبط ثم نلاحظ الفرق بين الصوت والرسم.","question":"أي كلمة ينطق فيها صوت مد غير مرسوم ألفًا مستقلة وفق المثال؟","correct":"هذا","wrong":["كتاب","طالب","قلم"],"practice":"اجمع أمثلة موثقة لحروف تنطق ولا تكتب وفسر رسم كل واحدة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"78296f45-5fb8-4b20-b6c2-257a0acb215f","n":2,"title":"الحروف التي تكتب ولا تنطق","passage":"تظهر في الرسم العربي حروف لا تنطق في بعض المواضع، مثل الألف الفارقة بعد واو الجماعة في «كتبوا» التي لا تمثل صوت مد إضافيًا في النطق القياسي. لا تضاف إلى واو الجمع الاسمية مثل «معلمو المدرسة».","question":"أين تأتي الألف الفارقة؟","correct":"بعد واو الجماعة في «كتبوا»","wrong":["بعد الواو في «معلمو»","بعد كل حرف واو","في بداية السؤال"],"practice":"اكتب ست جمل توظف واو الجماعة وأخرى واو الجمع مع بيان الرسم.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"78296f45-5fb8-4b20-b6c2-257a0acb215f","n":3,"title":"همزة ابن: إثباتها وحذفها","passage":"قد تُحذف ألف «ابن» في الرسم الإملائي عند وقوعها بين علمين ثانيهما أب للأول ضمن شروط معروفة، وتثبت في مواضع أخرى. تحتاج الدقة إلى مراعاة السياق والرسم ولا يصح حذفها كلما جاءت الكلمة في وسط جملة.","question":"ما الذي يحدد حذف ألف «ابن» في القاعدة المعروفة؟","correct":"استيفاء شروط موضعها بين علمين","wrong":["ورود كلمة ابن في أي جملة","كونها أول كلمة","وجود علامة استفهام"],"practice":"راجع ستة أمثلة متنوعة لكلمة ابن وعلل إثبات الألف أو حذفها.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"b0728f37-d81a-445d-b7e5-4f83b791e57c","n":1,"title":"أغراض التشبيه (فوائد التشبيه)","passage":"قد يُستخدم التشبيه لإيضاح صفة أو تقريب معنى ذهني أو تجميل صورة أو تقبيحها، ويتحدد أثره من العلاقة بين المشبه والمشبه به والسياق. في «المعلومة الواضحة كالمصباح» يفيد التشبيه تقريب أثر الإيضاح.","question":"ما وظيفة التشبيه في «المعلومة الواضحة كالمصباح»؟","correct":"تقريب معنى الإيضاح بصورة محسوسة","wrong":["سرد تاريخ معين","عد الكلمات","نفي الخبر"],"practice":"أنشئ ثلاثة تشبيهات مختلفة الغرض ثم فسر الأثر المقصود.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"b0728f37-d81a-445d-b7e5-4f83b791e57c","n":2,"title":"القصر","passage":"القصر تخصيص أمر بآخر بطريق بلاغي مناسب، وقد يتحقق بالنفي والاستثناء مثل «ما النجاحُ إلا نتيجةُ عملٍ» في سياق مجازي تعليمي، مع التنبه إلى أن الأحكام المطلقة تحتاج مراجعة. يتغير نوع القصر بحسب الاعتقاد والمقام.","question":"ما وسيلة القصر في تركيب «ما ... إلا»؟","correct":"النفي والاستثناء","wrong":["النداء","التوكيد اللفظي","المضاف إليه"],"practice":"استخرج مثالًا موثقًا لقصر بالنفي والاستثناء وآخر بإنما وناقش الغرض.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"b0728f37-d81a-445d-b7e5-4f83b791e57c","n":3,"title":"الإيجاز والإطناب","passage":"الإيجاز أداء المعنى بكلمات قليلة دون إخلال، والإطناب زيادة في المبنى لفائدة مثل التفصيل بعد الإجمال أو التوكيد. لا يعني الإطناب حشوًا بالضرورة، كما لا يضمن القصر وحده وضوح المعنى.","question":"متى يعد الإطناب مفيدًا؟","correct":"إذا أضاف تفصيلًا يخدم المعنى","wrong":["عندما يكرر بلا هدف","عندما يحذف الفكرة","إذا غابت الصلة بين الجمل"],"practice":"أعد صياغة فقرة مرة بإيجاز ومرة بتفصيل مفيد مع تحليل الفرق.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ad19e4d0-2494-4740-8696-168233d7bb86","n":1,"title":"النابغة — المدح","passage":"يتطلب درس المديح عند النابغة الذبياني أبياتًا صحيحة النسبة وسياق المخاطب؛ فلا يجوز تأليف بيت أو مناسبة تاريخية من العنوان. مثال مستقل يثني فيه زميل على دقة عمل آخر بموقف محدد، وهو نثر تدريبي.","question":"ما الذي يثبت صورة المدح في النص الشعري؟","correct":"شاهد صحيح من الأبيات وسياقه","wrong":["اسم الشاعر وحده","بيت مبتكر","عنوان القصيدة فقط"],"practice":"استخرج من النص المقرر أسلوب مديح موثقًا واشرح صورته وأثره.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ad19e4d0-2494-4740-8696-168233d7bb86","n":2,"title":"زهير بن أبي سلمى — الحكمة","passage":"تظهر الحكمة في بعض شعر زهير بن أبي سلمى بنبرة تأمل وتعليل، لكن لا يُنسب إليه قول من إنشاء ضاديوم. في موقف مستقل يراجع شخص قرارًا بعد اكتشاف خطأ؛ يقدم المثال فكرة التعلم من التجربة لا بيتًا تراثيًا.","question":"ما الدليل على الحكمة في قصيدة قديمة؟","correct":"بيت موثق يحمل معنى عامًا مع تعليل","wrong":["اسم الشاعر فقط","موقف مختلق","عدد الأبيات"],"practice":"اختر بيت حكمة موثقًا لزهير وفسر معنى الكلمات ومجال تطبيقه.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ad19e4d0-2494-4740-8696-168233d7bb86","n":3,"title":"عنترة — الفخر","passage":"يتطلب فخر عنترة بن شداد قراءة قصيدته الصحيحة وتحديد المخاطب ومعايير الفروسية في سياقها، دون افتراض قصة تاريخية من الصورة المجازية. مثال مستقل يعتز متعلم بوفائه بوعده رغم الصعوبة، ولا يمثل شعر عنترة.","question":"ما الذي يكشف غرض الفخر في بيت شعري؟","correct":"ألفاظ الاعتزاز والشواهد الصحيحة","wrong":["اللقب وحده","سيرة مختلقة","حرف الروي فقط"],"practice":"حلل فخرًا موثقًا في بيت منسوب بحق مع بيان الصورة والعاطفة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ad19e4d0-2494-4740-8696-168233d7bb86","n":4,"title":"الخنساء — الرثاء","passage":"يحتاج رثاء الخنساء إلى أبياتها المقررة لتحديد موضوع الفقد والنداء والتكرار بدقة؛ ولا يجوز اختلاق صيغة تعزية ونسبتها إليها. في مثال مستقل يتذكر راو صديقًا فقده وتغلب عليه مشاعر الحنين، وهو مشهد من ضاديوم.","question":"ما العاطفة الأساسية في الرثاء بوصفه غرضًا؟","correct":"الحزن على الفقيد","wrong":["المرح الرياضي","التهديد","التجارة"],"practice":"استخرج من قصيدة موثقة للخنساء شاهدًا للعاطفة واشرح وظيفة الصورة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ad19e4d0-2494-4740-8696-168233d7bb86","n":5,"title":"جميل بن معمر (جميل بثينة) — الغزل","passage":"يدرس الغزل من خلال المخاطب وضمائر القرب والبعد وصور الشوق في النص الصحيح المنسوب لجميل بن معمر، ولا تُخلق أبيات أو لقاءات له. مثال مستقل يكتب مسافر رسالة حنين لشخص عزيز دون وصفه بأنه شعر للشاعر.","question":"ما الذي يحدد المخاطب في قصيدة غزل؟","correct":"الضمائر والنداء والشواهد في النص","wrong":["العنوان وحده","حكاية مجهولة","القافية فقط"],"practice":"استخرج من النص المقرر لفظًا وصورة تدلان على الشوق، مع توثيق.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ad19e4d0-2494-4740-8696-168233d7bb86","n":6,"title":"حسان بن ثابت — في مدح الرسول صلى الله عليه وسلم","passage":"يحتاج شعر المديح النبوي المنسوب إلى حسان بن ثابت إلى نص محقق؛ ويُمنع اختلاق أبيات أو حديث ونسبته إلى النبي ﷺ أو إلى الشاعر. النشاط هنا على منهج التوثيق والتمييز بين الكلام الشعري والرواية الدينية.","question":"ما أول شرط لنقل بيت أو حديث في هذا الدرس؟","correct":"التحقق من متن صحيح ومصدر معتبر","wrong":["توليد بيت مناسب","نقل قول مجهول","الاكتفاء بعنوان المديح"],"practice":"مع المعلم، حلل شاهدًا شعريًا موثقًا وبيّن الغرض دون تحريف نص ديني.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"918ac729-7a69-413c-a7b5-e1e46ce5af83","n":1,"title":"الرسائل","passage":"تتكون الرسالة من مخاطب وغرض ومضمون وخاتمة، وقد تختلف الرسالة الأدبية عن الرسمية في التصوير والنبرة. في مثال مستقل يطلب طالب استعارة مرجع من مكتبة ويذكر المدة والسبب في لغة مهذبة.","question":"ما العنصر الذي يوضح المطلوب في الرسالة؟","correct":"طلب محدد مع سببه","wrong":["تحية بلا مضمون","تكرار كلمات","قافية شعرية"],"practice":"اكتب رسالة وظيفية وأخرى أدبية حول موضوع واحد وقارن بنيتهما.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"918ac729-7a69-413c-a7b5-e1e46ce5af83","n":2,"title":"الخطابة","passage":"تقوم الخطابة على التواصل مع جمهور معلوم بغرض إقناعه أو تعريفه مع مقدمة وحجج وانتقالات وخاتمة. في نموذج مستقل يدعو طالب زملاءه إلى تنظيم مكتبة القسم ويتجنب إعلان أرقام نجاح غير مثبتة.","question":"ما الذي يزيد قوة الخطبة الإقناعية؟","correct":"ترتيب الحجج وأمثلة ملائمة","wrong":["تكرار الشعار دون دليل","إخفاء الجمهور","إلغاء الفكرة"],"practice":"صمم خطة خطبة لدقيقتين مع افتتاح وحجتين وخاتمة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"918ac729-7a69-413c-a7b5-e1e46ce5af83","n":3,"title":"الخبر","passage":"الخبر بوصفه جنسًا نثريًا يروي حدثًا أو قولًا، ويختلف عن الخبر النحوي أو خبر الإعلام الحديث. عند نقل خبر تراثي نذكر المصدر والسياق ولا نعامل الرواية الأدبية بوصفها وثيقة مطلقة.","question":"ما المطلوب قبل نقل خبر تاريخي أدبي؟","correct":"التحقق من المصدر والسياق","wrong":["اختراع شخصية","الاعتماد على عنوان فقط","إلغاء الزمن"],"practice":"اختر خبرًا تراثيًا موثقًا وحلّل بنية الحدث ودرجة التثبت.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"918ac729-7a69-413c-a7b5-e1e46ce5af83","n":4,"title":"الحكاية المثلية","passage":"قد تستخدم الحكاية المثلية حيوانات أو شخصيات رمزية لاستخلاص عبرة من تتابع الأفعال والنتائج، وتحتاج النسخة المنقولة إلى مصدر معتمد. مثال مستقل يصور طائرًا يساعد آخر في تنظيم عشه ولا ينسب إلى كتاب تراثي.","question":"ما العنصر الضروري لفهم مغزى حكاية مثلية؟","correct":"العلاقة بين الحدث والنتيجة","wrong":["حفظ العنوان فقط","اختلاق أصل تاريخي","عدد الأسطر"],"practice":"اقرأ حكاية موثقة واكتب مخطط السبب والنتيجة والعبرة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"918ac729-7a69-413c-a7b5-e1e46ce5af83","n":5,"title":"المقامات","passage":"تتميز كثير من المقامات بالحكاية والأسلوب المسجوع والمفارقة والشخصية التي ينتظم حولها النص، لكن اختلاف المؤلفين يجعل التعميم يحتاج شواهد. مثال مستقل تبرز فيه حيلة لغوية في موقف اجتماعي دون نسبة التراث إليه.","question":"ما الذي قد يميز الأسلوب في مقامة معروفة؟","correct":"السجع والمفارقة ضمن حكاية","wrong":["الوزن الشعري فقط","غياب الأحداث","التعداد العددي"],"practice":"اختر مقامًا موثقًا وحلل عنصرًا سرديًا وآخر لغويًا.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"918ac729-7a69-413c-a7b5-e1e46ce5af83","n":6,"title":"النادرة","passage":"تقدم النادرة موقفًا موجزًا يقوم أحيانًا على مفارقة أو جواب ذكي أو تغير في توقع القارئ، لكن ليس كل موقف مضحك مصدرًا تاريخيًا صحيحًا. مثال مستقل يظن طالب أن كلمة على اللافتة تصف شخصًا ثم يكتشف أنها اسم غرفة.","question":"ما العنصر الذي أنتج المفارقة في المثال؟","correct":"اختلاف فهم الكلمة عن مقصد اللافتة","wrong":["طول الوصف","حرف الجر","الوزن الصرفي"],"practice":"اكتب نادرة من إنشائك قائمة على سوء فهم لغوي ثم وضح بنية المفارقة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"9f8e511d-8461-461d-b5c1-b6d8a7adaed7","n":1,"title":"أبو العتاهية — الزهد","passage":"لا يجوز إيراد أبيات للزهد على لسان أبي العتاهية ما لم تثبت من ديوان محقق. تدرس الصور الوعظية والتذكير بمرور الزمن في النص الصحيح، ويُفصل موقف الشاعر عن مثال ضاديوم المستقل لشخص يقدم عملًا نافعًا على التفاخر.","question":"ما الذي يدل على الزهد في موقف التدريب؟","correct":"تقديم منفعة الآخرين على المباهاة","wrong":["إخفاء النفع","الإنفاق لمجرد التفاخر","رفض مساعدة أحد"],"practice":"وثق بيتًا للشاعر يناقش قصر الحياة أو قيمة العمل ثم حلله.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"9f8e511d-8461-461d-b5c1-b6d8a7adaed7","n":2,"title":"البحتري — الوصف","passage":"يتطلب وصف البحتري في الشعر العباسي أبياتًا صحيحة لمعرفة الموضوع والحواس والصور، ولا يكفي اسم الشاعر لتعيين مشهد. مثال مستقل يصف انعكاس ضوء النهار على نافورة، ولا يمثل قصيدة.","question":"ما الأساس لفهم دقة الوصف في قصيدة؟","correct":"تفاصيل حسية موثقة في أبياتها","wrong":["اسم الشاعر فقط","وصف متخيل من القارئ","تاريخ بلا نص"],"practice":"استخرج صورتين من قصيدة موثقة للبحتري وفسر أثرهما.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"9f8e511d-8461-461d-b5c1-b6d8a7adaed7","n":3,"title":"أبو تمام — الوصف والحكمة","passage":"قد يجمع النص الشعري بين تصوير مشهد وتأمل يستخلص منه معنى عامًا، لكن لا تُنسب حكمة إلى أبي تمام من صياغة ضاديوم. في مثال مستقل يلاحظ متعلم إصرار فريق على حل مشكلة ثم يناقش سبب نجاحهم.","question":"ما الذي يحول وصف موقف إلى معنى حكمي؟","correct":"استنتاج فكرة عامة من الشاهد","wrong":["اسم الشاعر وحده","إلغاء النص","اختلاق قول"],"practice":"من قصيدة صحيحة لأبي تمام، استخرج صورة وحكمًا معللًا إن وردا.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"9f8e511d-8461-461d-b5c1-b6d8a7adaed7","n":4,"title":"المتنبي — الوصف والمدح","passage":"يُحلل الوصف والمدح في شعر المتنبي عبر المخاطب والصفات والصور والإيقاع في الأبيات الموثقة. لا تُخترع شواهد أو وقائع من سيرته. مثال مستقل يشيد زميل بدقة قائد فريق، وهو نثر تدريبي.","question":"ما الذي يثبت كون بيتٍ في غرض المديح؟","correct":"ألفاظ وصف المخاطب بإشادة ضمن سياقها","wrong":["العنوان وحده","تخمين مناسبة","عدد الحروف"],"practice":"حلل بيتًا موثقًا للمتنبي يصف مشهدًا أو شخصًا مع بيان أثر الصورة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"2bd6b464-b687-48dd-946a-50cd75689be9","n":1,"title":"ثورة الاتصالات","passage":"تغيرت وسائل نقل المعلومات من رسائل بطيئة إلى شبكات رقمية تتيح تفاعلًا سريعًا، لكن زيادة السرعة لا تضمن صحة المحتوى أو العدالة في الوصول. في نموذج مستقل يراجع فريق مصدر مقال قبل مشاركته رغم انتشاره الواسع.","question":"ما المشكلة التي لا تحلها سرعة الاتصال وحدها؟","correct":"التحقق من صحة المعلومات","wrong":["إرسال الملفات","تبادل الرسائل","إتاحة الحوار"],"practice":"اكتب مقارنة بين وسيلتين للاتصال مع فائدة ومخاطرة ومصدر موثق.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"2bd6b464-b687-48dd-946a-50cd75689be9","n":2,"title":"القنوات الفضائية","passage":"تعتمد القنوات الفضائية على بث مرئي ومسموع لجمهور واسع، وقد تختلف المواد بين خبر ورأي وإعلان وبرنامج تعليمي. يبحث الطالب عن المصدر والتاريخ ويميز طريقة المونتاج من مضمون الادعاء.","question":"ما الخطوة السليمة عند مشاهدة خبر مصور؟","correct":"فحص سياقه ومصدره وتاريخه","wrong":["الاكتفاء بالشعار","قبوله لكثرة المشاهدة","حذف الرابط"],"practice":"حلل تقريرًا مصورًا مأذونًا واكتب ما هو خبر وما هو تعليق.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"2bd6b464-b687-48dd-946a-50cd75689be9","n":3,"title":"الهاتف النقال","passage":"يفيد الهاتف النقال في التواصل والوصول إلى الخدمات، لكن استخدامه المسؤول يحتاج إدارة للوقت واحترامًا للخصوصية والتحقق من الروابط. في مثال مستقل يغلق طالب تنبيهات غير ضرورية خلال المراجعة ويبلغ أسرته بموعدها.","question":"ما الإجراء الذي ساعد الطالب على التركيز؟","correct":"تنظيم التنبيهات خلال المراجعة","wrong":["فتح كل الإشعارات","نشر معلومات خاصة","تجاهل المهمة"],"practice":"اكتب فقرة عن فائدتين للهاتف ومخاطرتين وطريقة للتعامل معهما.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"4c9cd9e3-8efe-4511-b6b7-9c74ceb85b19","n":1,"title":"مكافحة الفقر","passage":"يتطلب تحليل الفقر التمييز بين المؤشرات الاقتصادية وأسبابه المتعددة والسياسات المختلفة مع مصادر بيانات موثوقة، فلا نختزل المسألة في حكم أخلاقي على الأفراد. مثال مستقل تنظم جمعية تدريبًا مهنيًا طوعيًا وتقيّم نتائجه.","question":"ما الذي يجعل تقييم برنامج مجتمعي منصفًا؟","correct":"مؤشرات موثقة وظروف المشاركين","wrong":["الاعتماد على انطباع واحد","لوم الأفراد","اختلاق نتائج"],"practice":"اكتب عرضًا متوازنًا لحل مقترح مع معيار قياس ومصدر موثوق.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"4c9cd9e3-8efe-4511-b6b7-9c74ceb85b19","n":2,"title":"محو الأمية","passage":"تتجاوز محو الأمية معرفة الحروف إلى القدرة على استخدام القراءة والكتابة في الحياة اليومية، وتختلف البرامج باختلاف أعمار المتعلمين واحتياجاتهم. في مثال مستقل تتعلم مجموعة قراءة تعليمات دواء مع الرجوع للمختص عند الحاجة دون اتخاذ قرار علاجي من الدرس.","question":"ما النشاط الذي يوضح توظيف القراءة وظيفيًا؟","correct":"فهم تعليمات مكتوبة في سياقها","wrong":["عد الحروف دون فهم","حفظ عبارات بلا تطبيق","إلغاء السؤال"],"practice":"خطط نشاط محو أمية لقراءة إعلان عام مع أسئلة للفهم.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"4c9cd9e3-8efe-4511-b6b7-9c74ceb85b19","n":3,"title":"مشكلات القات","passage":"تُناقش قضايا القات من جوانب صحية واجتماعية واقتصادية بالرجوع إلى مصادر محلية وطبية موثوقة دون وصم مستخدميه أو وصف طرق استهلاكه. في نص أصلي يناقش فريق أثر المصروفات على ميزانية الأسرة ويطلب بيانات للتحقق.","question":"ما الضابط الأنسب لمناقشة أثر عادة اجتماعية صحية؟","correct":"بيانات موثوقة ولغة غير موصمة","wrong":["تعميم التجارب الفردية","اختلاق نسب","الاستهزاء بالأشخاص"],"practice":"اكتب فقرة تحليلية تميز بين دعوى صحية وأثر اجتماعي ومصدر كل منهما.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee51883b-758e-4258-86c5-ad76396fda9c","n":1,"title":"الموارد البحرية","passage":"تشمل الموارد البحرية كائنات ومواد وخدمات بيئية واقتصادية، وتتطلب إدارتها مراعاة الاستدامة والقوانين المحلية والبيانات البيئية. في مثال مستقل يقترح فريق توثيق حالة شاطئ قبل وضع خطة لتنظيفه.","question":"ما الذي يسبق تقييم استدامة مورد بحري؟","correct":"معرفة البيانات والقواعد البيئية المحلية","wrong":["استغلال بلا قياس","إلغاء التنظيم","تخمين نوع المورد"],"practice":"اكتب تقريرًا قصيرًا عن مورد بحري موثق وفائدة وحدٍّ بيئي.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee51883b-758e-4258-86c5-ad76396fda9c","n":2,"title":"الزراعة","passage":"تتأثر الزراعة بالماء والتربة والمناخ والمحصول وطريقة الإنتاج، ولا يمكن تعميم ممارسات منطقة على جميع البيئات. في مثال مستقل يقارن طالب احتياج نبتتين للماء وفق إرشادات موثقة ولا يجرب مواد خطرة.","question":"ما العامل الذي يجب مراعاته عند تخطيط زراعة مناسبة؟","correct":"المناخ والتربة والموارد المائية","wrong":["اسم المدينة فقط","لون الوعاء","عدد الصور"],"practice":"قارن محصولين بمراجع زراعية موثوقة من حيث الموارد والشروط.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee51883b-758e-4258-86c5-ad76396fda9c","n":3,"title":"دور القطاع الخاص في تنمية الاقتصاد","passage":"يسهم القطاع الخاص بطرق متنوعة في توفير السلع والخدمات وفرص العمل، لكن أثره يختلف باختلاف القواعد والمنافسة والبيئة الاقتصادية. في نموذج مستقل يدرب متجر صغير العاملين ويقيس رضا الزبائن بدل افتراض نجاح دون بيانات.","question":"ما الذي يساعد على تقويم أثر مشروع خاص؟","correct":"معيار موثق للأثر والنتائج","wrong":["إعلان دعائي فقط","إخفاء التكلفة","حكم مطلق"],"practice":"اكتب تحليلًا لمساهمة مشروع افتراضي مع فائدة وحدٍّ ومؤشر قياس.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"26b050d2-c843-4395-b8d0-85bec352292d","n":1,"title":"النظافة","passage":"تختلف ممارسات النظافة بحسب المكان والغرض، ويُفضل الرجوع إلى إرشادات صحية موثوقة عند تناول التعقيم والوقاية. في مثال مستقل ينظم فريق تنظيف ساحة مدرسة بمعدات مناسبة وإشراف دون التعامل مع مواد خطرة.","question":"ما الذي يجعل نشاط النظافة المدرسي مسؤولًا؟","correct":"السلامة وتوزيع المهام والمتابعة","wrong":["استخدام مواد مجهولة","ترك المخلفات","إخفاء الخطر"],"practice":"صمم تعليمات واضحة لنظافة مساحة عامة مع ذكر جهة إرشادية موثوقة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"26b050d2-c843-4395-b8d0-85bec352292d","n":2,"title":"تلوث البحار","passage":"قد تتلوث البحار بنفايات أو ملوثات متعددة، وتحتاج معرفة أثرها إلى مصادر علمية وقياسات، لا الاكتفاء بصورة واحدة. في مثال مستقل يسجل طلاب المخلفات المرئية على شاطئ ويُبلغون الجهة المسؤولة بدل لمس مواد مجهولة.","question":"ما السلوك الآمن عند ملاحظة مادة مجهولة على الشاطئ؟","correct":"إبلاغ المختصين وعدم لمسها","wrong":["حملها بلا حماية","نشر تقدير غير موثق","إخفاء المكان"],"practice":"اكتب تقرير ملاحظة بيئية مع فصل ما شوهد عما يتطلب تحليلًا علميًا.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"8020ba83-9e82-4df8-b96b-e4a8e5acff1a","n":1,"title":"السينما","passage":"تروي السينما القصص عبر الصورة والحوار والمونتاج والصوت، وقد تؤثر زاوية التصوير والإيقاع في استجابة المتلقي. في مثال مستقل يصور طلاب مشهد تعاون من لقطات مختلفة ثم يقارنون ما يتغير في الفهم.","question":"ما العنصر الذي يغير ترتيب الأحداث في الفيلم؟","correct":"المونتاج","wrong":["ضبط المبتدأ","بحر الشعر","عدد الحروف"],"practice":"حلل مشهدًا مأذونًا من حيث اللقطات والصوت والرسالة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"8020ba83-9e82-4df8-b96b-e4a8e5acff1a","n":2,"title":"المهرجانات","passage":"قد تجمع المهرجانات عروضًا فنية وثقافية ورياضية بحسب الجهة والهدف، وتحتاج كتابة تقرير عنها تاريخًا ومكانًا وبيان مصدر المعلومات. في مثال مستقل تنظم مدرسة مهرجانًا للقراءة وتعلن برنامجًا مناسبًا للجمهور.","question":"ما الذي يجعل تقرير مهرجان قابلًا للتحقق؟","correct":"مكان وزمان وبرنامج معلن","wrong":["اسم جذاب فقط","حكاية مجهولة","أرقام حضور مخترعة"],"practice":"اكتب تقريرًا عن مهرجان افتراضي موضحًا المعلومات المختلقة بوصفها تدريبًا.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"8020ba83-9e82-4df8-b96b-e4a8e5acff1a","n":3,"title":"الرحلات","passage":"تُستخدم الرحلات في التعلم لاكتشاف أماكن وتجارب مختلفة، ويحتاج وصف الرحلة إلى ترتيب الأحداث والتمييز بين الملاحظة والتفسير، ومراعاة قواعد السلامة. في مثال مستقل تزور مجموعة متحفًا وتدون ثلاثة أسئلة عن معروضات.","question":"ما التصرف الذي جعل الرحلة تعلمية في المثال؟","correct":"تدوين أسئلة وملاحظات عن المعروضات","wrong":["إلغاء الإرشادات","عدم مراجعة المعلومات","اختلاق تاريخ القطع"],"practice":"اكتب يومية رحلة مدرسية متخيلة تتضمن هدفًا وملاحظات وخلاصة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"b24bd1f5-e007-4972-8399-8f4ef59406e6","n":1,"title":"النوادي الرياضية","passage":"تمنح الأندية الرياضية فرصًا للتدريب والعمل الجماعي والمنافسة ضمن قواعد السلامة، وقد تختلف مواردها وتنظيمها. في مثال مستقل تضع لجنة نادٍ جدول استخدام الملعب وتتيح آلية اعتراض عادلة.","question":"ما الذي يساعد على عدالة الاستفادة من الملعب؟","correct":"جدول معلن ومعايير متساوية","wrong":["حجز سري","تجاهل المسؤوليات","إلغاء القواعد"],"practice":"اكتب لائحة مختصرة لناد مدرسي توضح الانضمام والحقوق والسلامة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"b24bd1f5-e007-4972-8399-8f4ef59406e6","n":2,"title":"ألعاب القوى","passage":"تضم ألعاب القوى مسابقات جري وقفز ورمي بمهارات وقواعد مختلفة، ويتطلب الحديث عن أرقامها التحقق من النتائج الرسمية وتاريخها. في مثال مستقل يتدرب فريق بإشراف تربوي على تسجيل أزمنة الجري دون المقارنة الجارحة بين الأفراد.","question":"ما الطريقة الصحيحة للإبلاغ عن رقم رياضي حقيقي؟","correct":"الاستناد إلى سجل رسمي مؤرخ","wrong":["تخمين الزمن","اختراع بطولة","الاعتماد على الذاكرة وحدها"],"practice":"قدّم بطاقة مسابقة واحدة في ألعاب القوى مع قانون عام ومصدر موثوق.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"b24bd1f5-e007-4972-8399-8f4ef59406e6","n":3,"title":"الألعاب الإفريقية","passage":"تجمع الألعاب الإفريقية رياضيين ومنافسات متعددة في دورات لها تواريخ ونتائج يجب التحقق منها من الجهات المنظمة. في مثال مستقل يبحث طالب عن دورة معينة في مصدر رياضي ويقارن معلومات خبرين قبل عرضها.","question":"ما المصدر الأوثق لنتائج دورة رياضية؟","correct":"سجلات الجهة المنظمة المؤرخة","wrong":["مقطع غير معروف","توقع شخصي","اسم المدينة فقط"],"practice":"أعد تقريرًا موجزًا عن دورة موثقة مع تمييز البيانات من الرأي.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"b06bb731-d820-49a9-9ae1-476a48b6cb19","n":1,"title":"ختان الإناث","passage":"ختان الإناث ممارسة ضارة تنتهك سلامة الفتيات وحقوقهن، وتؤكد الجهات الصحية الدولية عدم وجود فائدة صحية لها. لا ينبغي إيراد خطوات الممارسة أو تفاصيل مؤذية؛ يركز الدرس على الوقاية وحماية الطفل وطلب الدعم من جهات صحية وحماية موثوقة.","question":"ما الرسالة الصحية الأساسية حول ختان الإناث؟","correct":"ممارسة ضارة لا تحقق فائدة صحية","wrong":["إجراء وقائي ضروري","بديل للتطعيم","لا يؤثر في السلامة"],"practice":"اكتب رسالة توعية تحترم كرامة الفتيات وتذكر مرجعًا صحيًا دوليًا معتمدًا.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"b06bb731-d820-49a9-9ae1-476a48b6cb19","n":2,"title":"الأمراض النفسية (القلق)","passage":"القلق شعور إنساني قد يحدث في مواقف كثيرة، لكن تشخيص اضطراب قلق يحتاج تقييمًا مهنيًا وليس استنتاجًا من نص مدرسي. في مثال مستقل يشعر طالب بقلق قبل عرض، فيتحدث إلى شخص داعم وينظم التحضير دون وصم نفسه أو الآخرين.","question":"ما الذي لا يمكن تحديده من قصة قصيرة عن القلق؟","correct":"تشخيص اضطراب نفسي بدقة","wrong":["شعور الشخصية بالتوتر","وجود عرض مدرسي","استعداد الطالب"],"practice":"اكتب فقرة داعمة غير تشخيصية عن التعامل مع التوتر وطلب العون من مختص عند الحاجة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"b06bb731-d820-49a9-9ae1-476a48b6cb19","n":3,"title":"الأمراض المزمنة","passage":"تختلف الأمراض المزمنة في أسبابها وطرق إدارتها، ولا تصلح فقرة دراسية لتحديد دواء أو علاج لشخص بعينه. في مثال مستقل تراعي مدرسة احتياجات طالب لديه ترتيبات صحية خاصة مع الحفاظ على خصوصيته والتعاون مع الجهات المختصة.","question":"ما السلوك التربوي المناسب في المثال؟","correct":"احترام الخصوصية وتوفير دعم مناسب","wrong":["نشر المعلومات الصحية","وصف دواء بلا مختص","منع المشاركة دون سبب"],"practice":"حلل ملصقًا عامًا من جهة صحية موثوقة حول دعم المصابين دون وصم.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"916af7e2-e943-498b-9e73-7604c9114ca7","n":1,"title":"العلم بين الإنسانية والمصالح الاقتصادية","passage":"قد تتلاقى أهداف البحث العلمي مع تطوير منتجات وخدمات، لكن يمكن أن يظهر تضارب مصالح يحتاج شفافية ومراجعة أخلاقية. في مثال مستقل يعلن فريق مصدر تمويل دراسة ويقدم منهجها ونتائجها وحدودها.","question":"ما الذي يزيد ثقة الجمهور عند وجود تمويل للبحث؟","correct":"الإفصاح عن التمويل والمنهج والقيود","wrong":["إخفاء المصالح","اختلاق النتائج","الاعتماد على الشعار"],"practice":"اكتب مقارنة بين فائدة البحث العامة وحوافز التمويل مع مبدأ أخلاقي ومثال.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"916af7e2-e943-498b-9e73-7604c9114ca7","n":2,"title":"الاختراعات العلمية","passage":"تحتاج نسبة اختراع إلى شخص أو فترة إلى سجل موثق ودراسة للتطور التراكمي، ولا يصح اعتبار كل تطوير اختراعًا من الصفر. في مثال مستقل يطور فريق أداة تعليمية انطلاقًا من فكرة سابقة ويذكر ما أضافه وما لم يختبره.","question":"ما الإجراء الصحيح عند نسبة تطوير إلى فريق؟","correct":"تحديد الجديد والسابِق بمراجع","wrong":["ادعاء اختراع كل الأجزاء","إخفاء مصدر الفكرة","تخمين التاريخ"],"practice":"اختر اختراعًا معروفًا ووثق مراحل تطوره بمصدرين.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"916af7e2-e943-498b-9e73-7604c9114ca7","n":3,"title":"علماء مشاهير","passage":"تُبنى ترجمة عالم على الاسم والحقبة والعمل الصحيح النسبة والأثر الذي تؤيده مصادر تاريخية موثوقة، ولا يجوز تأليف مقولة ملهمة على لسانه. في مثال مستقل يتحقق طالب من بيانات عالم في مرجعين قبل نشر البطاقة.","question":"ما الذي يجب توثيقه عند كتابة سيرة عالم؟","correct":"مؤلفاته أو أعماله مع مصادرها","wrong":["قول مختلق","بطولة مجهولة","تخمين تاريخ"],"practice":"اكتب بطاقة قصيرة لعالم موثق تذكر عملًا حقيقيًا ومصدرين.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"08ed8896-3737-415d-8cee-5a8f1af3dcf0","n":1,"title":"الحقوق والواجبات","passage":"تُدرس الحقوق مع المسؤوليات المتبادلة ضمن قواعد قانونية وأخلاقية معلنة، ولا يصح أن تستخدم الواجبات لتبرير انتهاك الحقوق الأساسية. في مثال مستقل تنظم مدرسة استخدام قاعة بما يحفظ حق الجميع ويحدد واجب المحافظة عليها.","question":"ما العلاقة المناسبة بين حق الاستفادة من القاعة وواجب الطلاب؟","correct":"استعمالها بعدالة والمحافظة عليها","wrong":["احتكارها","إتلافها","إخفاء المواعيد"],"practice":"اكتب فقرة توازن حقًا وواجبًا في موقف واقعي مع قاعدة واضحة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"08ed8896-3737-415d-8cee-5a8f1af3dcf0","n":2,"title":"حرية التعبير","passage":"ترتبط حرية التعبير بإمكان طرح الرأي والمناقشة دون إكراه، مع وجود أطر قانونية وحدود لحماية حقوق الآخرين تختلف تفاصيلها حسب البلد. في مثال مستقل يناقش طلاب اقتراحًا علنًا ويقدّمون أسبابًا دون إساءة شخصية.","question":"ما ممارسة التعبير المسؤول في المثال؟","correct":"إبداء رأي معلل يحترم الأشخاص","wrong":["إهانة المخالف","منع الأسئلة","اختلاق اتهامات"],"practice":"ناقش موقفًا مدرسيًا يوازن بين التعبير واحترام الحقوق بلا دعاية حزبية.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"08ed8896-3737-415d-8cee-5a8f1af3dcf0","n":3,"title":"العدالة","passage":"تتطلب العدالة تطبيق قواعد معلنة بشكل منصف وإتاحة مراجعة القرارات بحسب النظام المناسب، مع عدم افتراض تماثل جميع الظروف. في مثال مستقل تعيد لجنة فحص توزيع المهام عندما يقدم عضو دليلًا على عدم الإنصاف.","question":"ما الخطوة التي تدعم العدالة في المثال؟","correct":"مراجعة القرار وفق معيار ودليل","wrong":["رفض الاعتراض بلا نظر","تطبيق قاعدة سرية","التهكم من المعترض"],"practice":"اكتب موقفًا يشرح كيف يتغير القرار بعد ظهور معلومة جديدة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":1,"title":"الميزان الصرفي","passage":"يساعد الميزان الصرفي على مقارنة حروف الجذر والزيادة، وتُوزن أصول الكلمة الثلاثية بـ«فعل»؛ فـ«كاتب» على وزن «فاعل» من الجذر «كتب» في استعمال اسم الفاعل. يلزم مراعاة الحذف والإعلال والتضعيف في أبواب أخرى.","question":"ما وزن «كاتب» الصرفي؟","correct":"فاعل","wrong":["فعول","مفعول","مفعال"],"practice":"زِن ست كلمات مجردة ومزيدة ثم حدد الجذر وحروف الزيادة.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":2,"title":"الجامد والمشتق (مقدمة)","passage":"المشتق يدل على معنى مأخوذ من أصل مع ارتباط بصيغة مثل «كاتب» من كتب، بينما الجامد لا يعامل في هذا الباب بوصفه مشتقًا من فعل في الاستعمال المدروس. تحتاج بعض الكلمات إلى تحليل لغوي تاريخي قبل القطع بنوعها.","question":"أي كلمة مشتقة من فعل كتب؟","correct":"كاتب","wrong":["قلم","بحر","سماء"],"practice":"صنف عشرة أسماء إلى جامد ومشتق مع دليل الصيغة والمعنى.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":3,"title":"اسم الفاعل","passage":"اسم الفاعل يشتق من الثلاثي على وزن «فاعل» غالبًا مثل «كاتب» ومن غير الثلاثي وفق بنية معروفة، ويدل على من قام بالفعل أو اتصف به في السياق. لا يساوي اسم الفاعل وظيفة الفاعل الإعرابية دائمًا.","question":"ما اسم الفاعل من «كتب»؟","correct":"كاتب","wrong":["مكتوب","كتابة","كتاب"],"practice":"كوّن أربعة أسماء فاعل من أفعال متنوعة واستعملها في جمل.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":4,"title":"اسم المفعول","passage":"يشتق اسم المفعول للدلالة على ما وقع عليه الفعل، مثل «مكتوب» من كتب، وتتغير صياغته بحسب بنية الفعل وتعديه. نميّز بين الصيغة الصرفية ودور الكلمة في الجملة.","question":"ما اسم المفعول من «كتب»؟","correct":"مكتوب","wrong":["كاتب","كتاب","كتابة"],"practice":"اشتق أسماء مفعول من أربعة أفعال متعدية موثقة واستعملها في السياق.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":5,"title":"اسم التفضيل","passage":"اسم التفضيل في صورته الشائعة على وزن «أفعل» مثل «أوضح»، ويُستخدم للموازنة بين شيئين في صفة مع مراعاة شروط الاشتقاق وأحكام الاستعمال. في «هذا التفسير أوضح من ذاك» تتعلق المفاضلة بالوضوح.","question":"ما اسم التفضيل في المثال؟","correct":"أوضح","wrong":["تفسير","من","ذاك"],"practice":"اكتب أربع جمل بأسماء تفضيل صحيحة مع تحديد المفضّل والمفضّل عليه.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":6,"title":"أفعال المقاربة","passage":"تدل أفعال المقاربة مثل «كاد» على قرب وقوع الخبر في استعمالها المعروف، نحو «كاد المطرُ يهطلُ». وقد تعمل عمل «كان» في أبوابها النحوية، مع شروط لصيغة الخبر تختلف بين الأفعال.","question":"أي فعل يدل على المقاربة في المثال؟","correct":"كاد","wrong":["يهطل","المطر","من"],"practice":"أنشئ ثلاث جمل بأفعال مقاربة ثم أعرب اسم الفعل وخبره بمساعدة مرجع نحوي.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":7,"title":"التوكيد المعنوي","passage":"تأتي ألفاظ مثل «نفس، عين، كل، جميع» لتوكيد اسم سابق عند استيفاء شروطها وارتباط الضمير حين يلزم. في «حضر الطلاب كلُّهم» توكيد معنوي يبين الشمول، ويتبع المؤكد في إعرابه.","question":"ما لفظ التوكيد في «حضر الطلاب كلهم»؟","correct":"كلهم","wrong":["حضر","الطلاب","من"],"practice":"اكتب أربعة أمثلة لتوكيد معنوي مختلف مع ضبط المعنى والإعراب.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":8,"title":"الاستثناء إجمالًا","passage":"يتضمن أسلوب الاستثناء مستثنى منه وأداة ومستثنى في تراكيب مثل «حضر الطلابُ إلا طالبًا»، ويختلف الإعراب بتأثير النفي والتمام والاتصال. نبدأ بفهم علاقة العموم بما أخرج منه قبل تحليل التفاصيل.","question":"ما أداة الاستثناء في المثال؟","correct":"إلا","wrong":["حضر","الطلاب","طالبًا"],"practice":"صنف ثلاثة أمثلة إلى تام مثبت وتام منفي وناقص منفي من مصدر نحوي.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":9,"title":"الاستثناء بإلا","passage":"في الاستثناء التام المثبت «حضر الطلاب إلا طالبًا» يُنصب المستثنى بـ«إلا» في التحليل المدرسي المعتاد، بينما تتنوع أحكام التام المنفي والمفرغ. يجب استحضار نوع الأسلوب قبل اختيار العلامة.","question":"ما إعراب «طالبًا» في المثال المثبت؟","correct":"مستثنى منصوب","wrong":["فاعل مرفوع","اسم مجرور","خبر إن"],"practice":"حلل ثلاثة أمثلة استثناء بإلا تختلف في النفي والتمام والاتصال.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":10,"title":"أسماء الزمان والمكان (مراجعة)","passage":"قد يدل اسم مشتق على زمان الحدث أو مكانه بحسب الوزن والسياق؛ فـ«مَطلع» يمكن أن يرتبط بوقت الطلوع أو موضعه في استعمال مناسب. لا تُستنتج الدلالة من الوزن وحده عندما تتشابه الصيغ.","question":"ما الذي يحدد معنى المكان من الزمان في كلمة مشتركة؟","correct":"سياق الاستعمال وقرائنه","wrong":["عدد الحروف","اسم الصفحة","قافية الجملة"],"practice":"اكتب أربعة أسماء زمان ومكان وضع لكل كلمة جملة واضحة المعنى.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":11,"title":"الاسم المقصور والمنقوص والممدود","passage":"الاسم المقصور آخره ألف لازمة مثل «فتى»، والمنقوص آخره ياء لازمة مكسور ما قبلها مثل «القاضي»، والممدود آخره همزة قبلها ألف زائدة مثل «صحراء». تختلف أحكام التثنية والجمع والإعراب بحسب النوع.","question":"أي كلمة اسم مقصور؟","correct":"فتى","wrong":["القاضي","صحراء","كتاب"],"practice":"صنف تسعة أسماء إلى مقصور ومنقوص وممدود مع تفسير آخر كل اسم.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"},{"cid":"014caf48-172f-402f-addf-0668128498f2","unit":"ee0a6fa0-2696-40a0-ab3d-44b159569410","n":12,"title":"التعجب","passage":"من صيغ التعجب القياسية «ما أفعَلَه!» و«أفعِلْ به!» بحسب الشروط، مثل «ما أجملَ التعاونَ!». لا تعتبر كل «ما» للتعجب؛ فقد تكون موصولة أو استفهامية أو نافية.","question":"ما الأسلوب في «ما أجمل التعاون»؟","correct":"تعجب قياسي","wrong":["نهي","خبر مثبت","نداء"],"practice":"أنشئ أربعة أساليب تعجب متنوعة واضبط الصيغ القياسية.","old":"DADYOOM_DJ_G11_OFFICIAL_PROGRAMME"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='DJ' AND c.id=r.cid
    AND g.grade_number=11 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'DJ_G11_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'DJ_G11_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'DJ_G11_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'DJ_G11_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_DJ_G11_ORIGINAL_60_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_DJ_G11_ORIGINAL_60_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_DJ_G11_ORIGINAL_60_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_DJ_G11_ORIGINAL_60_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'DJ_G11_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;